<?php
namespace davvag_events;

require_once dirname(__DIR__,2).'/lib/bootstrap.php';

final class EventService extends Service {
    public function getSession($req,$res) { return $this->run($req,$res,function($in){$actor=null;$identityError=null;try{$actor=Identity::actor();}catch(Fault $f){if(!in_array($f->reason,['AUTH_REQUIRED','PROFILE_REQUIRED'],true))throw $f;$identityError=['code'=>$f->reason,'message'=>$f->getMessage()];}return ['csrf'=>Identity::csrfToken(),'actor'=>$actor,'identityError'=>$identityError,'timezones'=>\DateTimeZone::listIdentifiers(),'templates'=>InvitationTemplates::listing(!empty($actor['admin'])),'setup'=>['drive'=>(bool)Drive::configured(),'stripe'=>(bool)Stripe::configured(),'smtp'=>is_file(TENANT_RESOURCE_LOCATION.'/global/config/emailsmtp.conf')]];}); }
    public function postSaveTemplate($req,$res) { return $this->run($req,$res,function($in){return InvitationTemplates::save(Identity::actor(),$in);},true); }
    public function getListEvents($req,$res) { return $this->run($req,$res,function($in){$actor=Identity::actor();$offset=Support::integer($in['offset']??0,0,100000);$rows=Store::rows('davvag_events_events',[],50,$offset);$out=[];foreach($rows as $r){$e=is_string($r->state)?json_decode($r->state,true):json_decode(json_encode($r->state),true);$e['revision']=(int)$r->revision;try{$role=Identity::authorize($e,$actor,'view');$out[]=Domain::summary($e,$role);}catch(Fault $f){if($f->reason!=='FORBIDDEN')throw $f;}}return ['events'=>$out,'nextOffset'=>count($rows)===50?$offset+50:null];}); }
    public function getEvent($req,$res) { return $this->run($req,$res,function($in){$a=Identity::actor();$e=Store::load($in['eventId']??'');$view=Domain::adminView($e,$a);if($view['role']==='administrator'){Store::save($e,$e['revision'],$a['id'],'privileged_read');$view['revision']=$e['revision'];}return $view;}); }
    public function postSaveEvent($req,$res) { return $this->run($req,$res,function($in){$a=Identity::actor();if(empty($in['eventId'])){$e=Domain::create($in,$a['id']);Store::save($e,0,$a['id'],'create');}else{$r=Store::mutate($in['eventId'],$a,'edit',function(&$e)use($in){Domain::edit($e,$in);},Support::integer($in['revision']??-1,0,2147483647));$e=$r['event'];}return Domain::adminView($e,$a);},true); }
    public function postTransition($req,$res) { return $this->run($req,$res,function($in){$a=Identity::actor();$r=Store::mutate($in['eventId']??'',$a,'owner',function(&$e)use($in){Domain::transition($e,$in['status']??'');},$in['revision']??-1);return Domain::adminView($r['event'],$a);},true); }
    public function postMember($req,$res) { return $this->run($req,$res,function($in){$a=Identity::actor();$r=Store::mutate($in['eventId']??'',$a,'members',function(&$e)use($in){$id=(string)Support::integer($in['profileId']??0,1,2147483647);$p=Store::rows('profile',[['column'=>'id','operator'=>'=','value'=>$id]],1);if(!$p||empty($p[0]->linkeduserid))Support::fail('PROFILE','Select an existing profile linked to a user.');if($id===$e['ownerProfile'])Support::fail('MEMBER','The owner does not need a membership.');$e['members']=array_values(array_filter($e['members'],function($m)use($id){return $m['profileId']!==$id;}));if(!empty($in['remove']))return;$role=Support::choice($in['role']??'',['manager','checkin','moderator']);$grants=$in['grants']??[];if(!is_array($grants))Support::fail('GRANTS','Invalid grants.');foreach($grants as $g)Support::choice($g,['edit','guests','seating','moderate','checkin','reports','media']);$e['members'][]=['profileId'=>$id,'role'=>$role,'grants'=>array_values(array_unique($grants))];},$in['revision']??-1);return Domain::adminView($r['event'],$a);},true); }
    public function getPreview($req,$res) { return $this->run($req,$res,function($in){$a=Identity::actor();$e=Store::load($in['eventId']??'');Identity::authorize($e,$a,'edit');$d=$e['draft'];unset($d['gateHash']);return ['id'=>$e['id'],'invitation'=>$d,'preview'=>true];}); }
    public function getReport($req,$res) { return $this->run($req,$res,function($in){$a=Identity::actor();$e=Store::load($in['eventId']??'');Identity::authorize($e,$a,'reports');return ['summary'=>Domain::summary($e,'report'),'seating'=>Seating::lookup($e,array_column($e['guests'],'id')),'audit'=>array_slice(array_reverse($e['audit']),0,100),'jobs'=>array_map(function($j){unset($j['payload'],$j['lease']);return $j;},$e['jobs'])];}); }
    public function postRetryJob($req,$res) { return $this->run($req,$res,function($in){$a=Identity::actor();$r=Store::mutate($in['eventId']??'',$a,'owner',function(&$e)use($in){foreach($e['jobs'] as &$j)if($j['id']===($in['jobId']??'')){if(in_array($j['status'],['running','uncertain'],true))Support::fail('JOB_REVIEW','Review delivery before rotating and queuing a new invitation.',409);$j['status']='queued';$j['attempts']=0;$j['runAt']=Support::now();$j['reason']='';return ['queued'=>true];}Support::fail('JOB','Job not found.',404);});return $r['value'];},true); }
    public function postDeleteEvent($req,$res) { return $this->run($req,$res,function($in){$a=Identity::actor();$r=Store::mutate($in['eventId']??'',$a,'delete',function(&$e)use($in){if($e['status']!=='archived'||($in['confirmation']??'')!==$e['draft']['title'])Support::fail('DELETE','Archive the event and confirm its title first.');foreach($e['orders'] as $order)if($order['amount']>0&&!in_array($order['status'],['refunded','cancelled','expired'],true))Support::fail('FINANCIAL_RECORDS','Resolve paid orders and refunds before deleting event records.',409);foreach($e['media'] as $m)if(!empty($m['driveId'])&&empty($in['keepDriveFiles']))Support::fail('DRIVE_FILES','Choose to retain host Drive files. Remove app-created files in Drive before deleting metadata.');$e['guests']=[];$e['parties']=[];$e['assignments']=[];$e['greetings']=[];$e['tokens']=[];$e['orders']=[];$e['tickets']=[];$e['checkins']=[];$e['operations']=[];foreach($e['jobs'] as &$j)if($j['type']!=='cleanup'){$j['status']='done';$j['payload']=[];}unset($j);$e['draft']['message']='';$e['published']=null;$e['deletedAt']=Support::now();Jobs::enqueue($e,'cleanup',$e['id'],'delete-cleanup');},$in['revision']??-1);return ['deleted'=>true,'retainedAudit'=>true,'driveFilesRetained'=>true];},true); }
}
